// Generated by 08_AUTOMATION/Scripts/episode/figma_fill.py — do not edit code.js by hand.
// Fills every card on the "<EPISODE> — Graphics Map" page with a real ALUX template instance.
// Runs in Figma Desktop because the templates use Gilroy (a local font the remote MCP can't edit).
const DATA = __DATA__;
const TEMPLATE = {
  chapter: 'ALUX / Chapter', stat: 'ALUX / Stat', stamp: 'ALUX / Stamp', quickfact: 'ALUX / Quick fact',
  still: 'ALUX / Still frame', illustration: 'ALUX / Illustration card', bio: 'ALUX / Bio card',
  lower: 'ALUX / Lower third', compare: 'ALUX / Chart — Compare',
};
const OVERLAY = new Set(['stat', 'stamp', 'bio', 'lower']); // transparent templates: show a footage stand-in behind
const THUMB_W = 444, SCALE = THUMB_W / 3840;

async function main() {
  const gilroy = (await figma.listAvailableFontsAsync()).filter(f => f.fontName.family === 'Gilroy').map(f => f.fontName.style);
  for (const s of ['Regular', 'Medium', 'Bold', 'Heavy']) {
    if (!gilroy.includes(s)) return figma.closePlugin(`Gilroy ${s} belum terinstal — install Gilroy_fixed lalu restart Figma.`);
    await figma.loadFontAsync({ family: 'Gilroy', style: s });
  }
  await figma.loadFontAsync({ family: 'Gilroy', style: 'Bold' });

  const tplPage = figma.root.children.find(p => p.name === 'ALUX — Templates');
  const mapPage = figma.root.children.find(p => p.name.startsWith(DATA.episode.toUpperCase()) || p.name.startsWith('EP' + DATA.episode));
  if (!tplPage || !mapPage) return figma.closePlugin('Page "ALUX — Templates" atau Graphics Map episode tidak ditemukan.');
  await tplPage.loadAsync(); await mapPage.loadAsync();
  const comp = {};
  for (const [k, name] of Object.entries(TEMPLATE)) comp[k] = tplPage.findOne(n => (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET') && n.name === name);
  const vars = await figma.variables.getLocalVariablesAsync('COLOR');
  const paintVar = (name, opacity) => { const p = figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', vars.find(v => v.name === name)); return opacity == null ? p : { ...p, opacity }; };

  const repair = await repairFonts(mapPage);
  let filled = 0, labelled = 0; const problems = [];
  for (const card of DATA.cards) {
    try { await fillCard(card); } catch (e) { problems.push(card.id + ': ' + (e && e.message ? e.message : String(e))); }
  }
  async function fillCard(card) {
    const node = mapPage.findOne(n => (n.type === 'COMPONENT' || n.type === 'FRAME') && n.name.startsWith(card.id + ' '));
    if (!node) { problems.push(card.id + ': kartu tidak ditemukan'); return; }
    const thumb = node.findOne(n => n.name === 'Frame 16:9');
    if (!thumb) { problems.push(card.id + ': Frame 16:9 tidak ada'); return; }

    const f = card.fill;
    if (!f || f.hold) {
      placeholder(thumb, card.type, f && f.hold ? 'HOLD — ' + f.hold : 'TEMPLATE BELUM ADA', !!(f && f.hold), paintVar);
      labelled++; return;
    }
    const src = comp[f.template];
    if (!src) { problems.push(card.id + ': template ' + f.template + ' tidak ada'); return; }

    thumb.layoutMode = 'NONE';
    for (const c of [...thumb.children]) c.remove();
    thumb.clipsContent = true;
    thumb.fills = OVERLAY.has(f.template)
      ? [{ type: 'GRADIENT_LINEAR', gradientTransform: [[1, 0, 0], [0, 1, 0]], gradientStops: [
          { position: 0, color: { r: 0.22, g: 0.25, b: 0.29, a: 1 } }, { position: 1, color: { r: 0.42, g: 0.45, b: 0.48, a: 1 } }] }]
      : [paintVar('navy/950')];

    const inst = src.type === 'COMPONENT_SET' ? src.defaultVariant.createInstance() : src.createInstance();
    thumb.appendChild(inst);
    inst.x = 0; inst.y = 0;
    if (f.variant) inst.setProperties(f.variant);
    const keys = Object.keys(inst.componentProperties);
    const props = {};
    for (const [name, val] of Object.entries(f.props || {})) {
      const key = keys.find(k => k.split('#')[0] === name);
      if (key) props[key] = val; else problems.push(`${card.id}: properti "${name}" tidak ada`);
    }
    inst.setProperties(props);
    if (f.source) {
      const s = inst.exposedInstances.find(e => e.name === 'ALUX / Source label') || inst.findOne(n => n.type === 'INSTANCE' && n.name === 'ALUX / Source label');
      if (s) { const sk = Object.keys(s.componentProperties).find(k => k.startsWith('Source')); s.setProperties({ [sk]: f.source }); }
    }
    if (f.template === 'chapter') setRoute(inst, f.route, paintVar);
    // Instances can't override child geometry, so data-driven bar lengths need a detached copy.
    const gfx = f.template === 'compare' ? inst.detachInstance() : inst;
    if (f.template === 'compare') setBars(gfx, f, paintVar);
    gfx.rescale(SCALE);
    filled++;
  }
  figma.closePlugin(`${DATA.episode}: ${filled} kartu diisi template · ${labelled} placeholder · font diperbaiki ${repair.fixed}` + (repair.failed ? ` (gagal ${repair.failed})` : '') + (problems.length ? ` · ${problems.length} masalah: ${problems.slice(0, 3).join('; ')}` : ''));
}

// Cards without a template get a clean placeholder: type name + status, in the fixed Gilroy.
function placeholder(thumb, type, status, hold, paintVar) {
  thumb.layoutMode = 'NONE';
  for (const c of [...thumb.children]) c.remove();
  thumb.clipsContent = true;
  thumb.fills = [paintVar('navy/900')];
  const mk = (chars, style, size, fill, y) => {
    const t = figma.createText(); t.fontName = { family: 'Gilroy', style }; t.fontSize = size; t.characters = chars;
    t.fills = [fill]; thumb.appendChild(t); t.x = 20; t.y = y; t.resize(404, t.height); t.textAutoResize = 'HEIGHT'; return t;
  };
  mk(type.toUpperCase(), 'Bold', 12, paintVar('slate/500'), 20);
  mk(status, 'Bold', hold ? 15 : 20, paintVar(hold ? 'red/500' : 'gold/500'), 150);
}

// Text set in the broken Drive originals shows up as family "Gilroy-Bold" with a junk style ("☞").
// Those fonts are gone once Gilroy_fixed is installed, so map them onto the fixed family.
async function repairFonts(page) {
  let fixed = 0, failed = 0;
  for (const t of page.findAllWithCriteria({ types: ['TEXT'] })) {
    let segs;
    try { segs = t.getStyledTextSegments(['fontName']); } catch (e) { failed++; continue; }
    const broken = segs.filter(s => /^Gilroy-/.test(s.fontName.family));
    if (!broken.length) continue;
    for (const s of broken) {
      const style = s.fontName.family.replace('Gilroy-', '');
      const target = { family: 'Gilroy', style: ['Light', 'Regular', 'Medium', 'Bold', 'Heavy'].includes(style) ? style : 'Regular' };
      try { t.setRangeFontName(s.start, s.end, target); fixed++; } catch (e) { failed++; }
    }
  }
  return { fixed, failed };
}

function setBars(inst, f, paintVar) {
  ['Bar 2023', 'Bar 2024'].forEach((rowName, i) => {
    const row = inst.findOne(n => n.name === rowName);
    if (!row) return;
    const bar = row.findOne(n => n.name === 'Value bar');
    const track = row.findOne(n => n.name === 'Track');
    bar.resize(Math.max(8, track.width * f.bars[i]), bar.height);
    bar.fills = [paintVar(f.barColor)];
  });
}

// Chapter k (0-based): stops 0..k and segments 0..k-1 cyan, halo on stop k. Colour only —
// instances can't move or resize their layers.
function setRoute(inst, k, paintVar) {
  const route = inst.findOne(n => n.name.startsWith('Route map'));
  if (!route) return;
  const stops = route.children.filter(n => n.name.startsWith('Stop '));
  const segs = route.children.filter(n => n.name.startsWith('Segment '));
  stops.forEach((e, i) => {
    e.fills = [paintVar(i <= k ? 'cyan/500' : 'navy/700')];
    e.strokes = i === k ? [paintVar('cyan/500', 0.3)] : [];
  });
  segs.forEach((r, i) => { r.fills = [paintVar(i < k ? 'cyan/500' : 'navy/700')]; });
}

main().catch(e => figma.closePlugin('Gagal: ' + (e && e.message ? e.message : String(e))));
